scwin.vScrenID = "ULDSTF41000.xml";
scwin.fr_SecuGrpId = "";
scwin.gDepCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD);
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM);
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsur = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};
scwin.fn_list_sync = function() {
    var vCmpCd = scwin.fn_getCondition();
    var vCorrCd = $c.stf.getObjectValue(rdo_CorrCd);
    var vEmpNo = $c.stf.getObjectValue(cmb_EMP_NO);
    var vDepCd = $c.stf.getObjectValue(cmb_DEP_CD);
    var vIsurCd = $c.stf.getObjectValue(txb_ISUR_CD);
    var vMarketTpCd = "";
    if (js_market == "1" || js_market == "2") {
        vMarketTpCd = js_market;
    } else {
        vMarketTpCd = $c.stf.getObjectValue(rdo_MARKET_TP_CD);
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&outputMessageId=LIST_TRADING_CMPR_OUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.listedsearch.listingtrsystem.cmpr.select.condition" + "&{P}param01=" + vCmpCd + "&{P}param02=" + vCmpCd + "&{P}param03=" + vCorrCd + "&{P}param04=" + vCorrCd + "&{P}param05=" + vEmpNo + "&{P}param06=" + vEmpNo + "&{P}param07=" + vDepCd + "&{P}param08=" + vDepCd + "&{P}param09=" + vIsurCd + "&{P}param10=" + vIsurCd + "&{P}param11=" + vMarketTpCd + "&{P}param12=" + vMarketTpCd;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_List);
};
scwin.fn_SetCode = function() {
    scwin.gDepCd = js_dep_cd;

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)	
    //dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_DEP_CD.Reset();

    //담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)	
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_EMP_NO.Reset();
};



