scwin.fn_getCondition = function() {
    var vStatCnt = 0;
    var vStatCond = '';
    if (chb_stat_99.checked == true) {
        vStatCond = '';
        vStatCnt++;
    }
    if (chb_stat_01.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '1');
        vStatCnt++;
    }
    if (chb_stat_02.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '2');
        vStatCnt++;
    }
    if (chb_stat_03.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '3');
        vStatCnt++;
    }
    if (chb_stat_04.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '4');
        vStatCnt++;
    }
    if (chb_stat_05.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '5');
        vStatCnt++;
    }
    if (chb_stat_06.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '6');
        vStatCnt++;
    }
    if (chb_stat_07.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '7');
        vStatCnt++;
    }
    if (chb_stat_08.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '8');
        vStatCnt++;
    }
    if (chb_stat_09.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '9');
        vStatCnt++;
    }
    if (chb_stat_10.checked == true) {
        vStatCond = scwin.fn_getCondValue(vStatCnt, vStatCond, '10');
        vStatCnt++;
    }
    return vStatCond;
};
scwin.fn_getCondValue = function(pCnt, pVal, vCode) {
    if (pCnt > 0) {
        pVal += "," + vCode + "";
    } else {
        pVal = vCode;
    }
    return pVal;
};
scwin.fn_allCheck = function() {
    var checkArray = [chb_stat_01, chb_stat_02, chb_stat_03, chb_stat_04, chb_stat_05, chb_stat_06, chb_stat_07, chb_stat_08, chb_stat_09, chb_stat_10];
    if (chb_stat_99.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.img_COM_NM_onclick = function() {
    fn_GetPar = fn_GetParIsur;
    fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.btn_Excel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_List, "상장시스템/매매시스템 자료비교목록", "", "8");
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_DEP_CD_OnLoadError = function() {
    $c.stf.alert_error(dts_DEP_CD);
};
scwin.dts_EMP_NO_OnLoadError = function() {
    $c.stf.alert_error(dts_EMP_NO);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.dts_DEP_CD_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_DEP_CD, js_dep_cd) ;		

};
scwin.dts_EMP_NO_OnLoadCompleted = function(rowcount) {
    //setObjectValue(cmb_EMP_NO, js_emp_no) ;	

};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.cp.valueOfIndex(cmb_DEP_CD, "VALUE", cmb_DEP_CD.getSelectedIndex());
    if (scwin.gDepCd == '') {
        $c.stf.setObjectValue(cmb_DEP_CD, '');
    }
    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
    dts_EMP_NO.sort("DEP_CD", 0);
    //dts_EMP_NO.sort(); // W-Craft 주석처리 

};
scwin.dts_EMP_NO_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "DEP_CD") == scwin.gDepCd || dts_EMP_NO.getCellData(row, "DEP_CD") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.txb_ISUR_CD_onkeyup = function() {
    if (txb_ISUR_CD.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_ISUR_CD_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.chb_stat_99_onclick = function() {
    scwin.fn_allCheck();
};
scwin.chb_stat_02_onclick = function() {
    chb_stat_99.setValue(0);
};
scwin.chb_stat_03_onclick = function() {
